type Exp = u128;
struct BlockSimulator {
    pub left_tape: Vec<BlockSymbol>,
    pub right_tape: Vec<BlockSymbol>,
    pub state: HigherState,
    pub base_steps: u128,
    pub self_steps: u64,
}
impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s_exp = match *self {
            Run(_, n) => {
                if n == 1 {
                    ""
                } else {
                    &format!("^{}", n)
                }
            }
            _ => "",
        };
        write!(f, "{}{}", s0, s_exp)
    }
}

// End of customizable code

impl BlockSimulator {
    fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            // 42: L X c> D0 111
            // 50: L X S0 e> 111
            // 116: L X^3 S0 D1 c> 1001
            left_tape: vec![L, Run(X, 1)],
            right_tape: vec![R, K, M, D0],
            state: HigherState::RightC,
            base_steps: 42,
            self_steps: 0,
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        use BlockSymbol::*;
        use HigherState::*;
        use RunSymbolType::*;

        // Halting rules:
        // B> K -> ***HALT***
        // a> J -> ***HALT***
        // B> M -> ***HALT***
        if matches!(
            (self.state, self.right_tape.last()),
            (RightB, Some(K | M)) | (RightA, Some(J))
        ) {
            return Err(SimError::Halted);
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps += new_base_steps;
        self.self_steps += 1;
        Ok(())
    }

    fn at_transition(&self) -> bool {
        use BlockSymbol::*;
        use HigherState::*;
        use RunSymbolType::X;
        // matches!(self.state, Left | LeftA)
        self.left_tape
            .iter()
            .all(|b| matches!(b, L | Run(X, _) | S0 | D1))
            && !matches!(self.right_tape.last(), Some(D0 | D1 | Run(X, _)))
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
enum LongHead {
    H0,
    H1,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Digit {
    D0,
    D1,
}

impl Digit {
    fn to_symbol(&self) -> BlockSymbol {
        match self {
            Digit::D0 => BlockSymbol::D0,
            Digit::D1 => BlockSymbol::D1,
        }
    }
}

const N_BITS_PACKED: usize = 64;
struct PackedDigit(u64);

#[derive(Clone, Copy, PartialEq, Eq)]
enum DigitHead {
    /// C0 = D0 h1
    C0,
    /// C1 = D1 h0
    C1,
}

impl DigitHead {
    fn apply_head(&mut self, h: LongHead) {
        if h == LongHead::H1 {
            if *self == DigitHead::C0 {
                *self = DigitHead::C1;
            } else {
                *self = DigitHead::C0;
            }
        }
    }
}

