use std::collections::{HashMap, HashSet};

type Tape = Vec<BlockSymbol>;

fn build_graph_to_halting() -> (HashSet<Tape>, HashMap<(LongHead, Tape), RightResult>) {
    let rtape = {
        use BlockSymbol::*;
        // vec![R, M, J, K]
        vec![R]
    };
    let mut frontier: VecDeque<Tape> = VecDeque::new();
    frontier.push_back(rtape);

    let mut visited: HashSet<Tape> = HashSet::new();
    let mut halters: HashSet<Tape> = HashSet::new();
    let mut graph: HashMap<(LongHead, Tape), RightResult> = HashMap::new();

    while visited.len() < 1000000
        && halters.len() < 3
        && let Some(next) = frontier.pop_front()
    {
        // println!("{}", RightResult::Tape(next.clone()));
        visited.insert(next.clone());
        for h in [LongHead::H0, LongHead::H1] {
            let res = apply_head_right_end(h, next.clone());
            match &res {
                RightResult::Halt => {
                    println!(
                        "{:?} {} halts",
                        h,
                        RightResult::Continue {
                            rtape: next.clone(),
                            new_digits: Vec::new()
                        }
                    );
                    halters.insert(next.clone());
                    println!("{}", visited.len());
                }
                RightResult::Continue {
                    rtape,
                    new_digits: _,
                } => {
                    if !visited.contains(rtape)
                        && !frontier.contains(rtape)
                        && !halters.contains(rtape)
                    {
                        frontier.push_back(rtape.clone());
                    }
                }
            }
            // store the fact that (h, next) => (new digits, rtape) or halt
            graph.insert((h, next.clone()), res);
        }
    }
    (halters, graph)
}

enum PartialFormat {
    String(String),
    Run1(usize),
}

fn run_length_format_rtape(rtape: &Tape) -> String {
    let mut out = String::new();
    for s in rtape.iter().rev() {
        use BlockSymbol::*;
        match s {
            R => (),
            K => out.push_str("10"),
            J => out.push_str("01"),
            M => out.push_str("11"),
            U => out.push_str("00"),
            _ => unimplemented!(),
        }
    }
    let mut out2 = out.trim_end_matches('0').to_owned();

    let mut runs: Vec<(char, usize)> = Vec::new();
    for c in out2.chars() {
        if let Some((c0, n)) = runs.last_mut()
            && *c0 == c
        {
            *n += 1;
        } else {
            runs.push((c, 1));
        }
    }

    let mut out3: Vec<PartialFormat> = Vec::new();
    for (c, n) in runs {
        if c == '1' && n >= 5 {
            out3.push(PartialFormat::Run1(n));
        } else {
            if let Some(PartialFormat::String(s)) = out3.last_mut() {
                for _ in 0..n {
                    s.push(c);
                }
            } else {
                let mut s_new = String::new();
                for _ in 0..n {
                    s_new.push(c);
                }
                out3.push(PartialFormat::String(s_new));
            }
        }
    }
    let out4: Vec<String> = out3
        .iter()
        .map(|p| match p {
            PartialFormat::String(s) => s.clone(),
            PartialFormat::Run1(n) => format!("1^{}", n),
        })
        .collect();
    out2 = out4.join(" ");

    out2.push('$');
    out2
}

fn bfs(graph: &HashMap<(LongHead, Tape), RightResult>, start: Tape, dest: Tape) {
    let mut frontier: VecDeque<Tape> = VecDeque::new();
    frontier.push_back(start.clone());

    let mut parents: HashMap<Tape, Tape> = HashMap::new();

    while let Some(v) = frontier.pop_front() {
        if v == dest {
            break;
        }
        for h in [LongHead::H0, LongHead::H1] {
            if let Some(RightResult::Continue {
                rtape: w,
                new_digits: _,
            }) = graph.get(&(h, v.clone()))
                && !parents.contains_key(w)
            {
                parents.insert(w.clone(), v.clone());
                frontier.push_back(w.clone());
            }
        }
    }
    let mut path: VecDeque<Tape> = VecDeque::new();
    path.push_back(dest.clone());
    let mut curr = dest.clone();
    loop {
        curr = parents.get(&curr).unwrap().clone();
        path.push_front(curr.clone());
        if curr == start {
            break;
        }
    }
    let path_s: Vec<String> = path.iter().map(|t| run_length_format_rtape(t)).collect();
    println!("{}", path_s.join(" -> "));
    println!("{}", path.len());
}

fn bfs_to_halting() {
    let (halters, graph) = build_graph_to_halting();

    // print some of the graph
    let n_print = 50;
    let mut count = 0;
    for ((h, rtape0), res) in &graph {
        if rtape0.len() < 6
            && let RightResult::Continue {
                rtape: rtape_new,
                new_digits: _,
            } = res
            && rtape_new.len() < 6
        {
            println!(
                "{:?} {} -> {}",
                h,
                RightResult::Continue {
                    rtape: rtape0.clone(),
                    new_digits: Vec::new()
                },
                res
            );
            count += 1;
            if count >= n_print {
                break;
            }
        }
    }

    for halter in halters {
        let rtape = {
            use BlockSymbol::*;
            // vec![R, M, J, K]
            vec![R]
        };
        bfs(&graph, rtape, halter);
    }
}

